model.some_package.package_helper.raw_code:
{{
    config(
        description = 'Customers as the shop platform exports them. Grain is one row per customer.
                    joined_at is the first order date rather than the account creation date.',
    )
}}

with s_shop_customers as (

    select * from {{ source('shop_source', 'customers') }}

),

rename_and_cast as (

    select

        -- Keys
        cast(customer_id as {{ dbt.type_string() }})   as customer_natural_key,

        -- Attributes
        cast(name as {{ dbt.type_string() }})          as customer_name,

        -- Temporal
        cast(joined_at as {{ ra_type_date() }})        as customer_joined_dt

    from s_shop_customers

),

final as (

    select * from rename_and_cast

)

select * from final

model.tiny_shop.int_shop__orders.raw_code:
{{
    config(
        description = 'Orders joined to the customer who placed them. A working step on the way to
                    the order fact, not a table to report from. Grain is one row per order.',
    )
}}

with s_orders as (

    select * from {{ ref('stg_shop__orders') }}

),

s_customers as (

    select * from {{ ref('stg_shop__customers') }}

),

joined as (

    select

        -- Keys
        s_orders.order_natural_key,
        s_orders.customer_natural_key,

        -- Temporal
        s_orders.order_placed_dt,

        -- Metrics
        s_orders.order_total_amount

    from s_orders

    left join s_customers
        on s_customers.customer_natural_key = s_orders.customer_natural_key

),

final as (

    select * from joined

)

select * from final

